    @Test
    public void testDecryptPasswords() throws KuraException {
        // test password decryption

        ConfigurationServiceImpl cs = new TestConfigurationService();

        ComponentConfigurationImpl config = new ComponentConfigurationImpl();
        Map<String, Object> props = new HashMap<>();
        config.setProperties(props);
        String passStr = "passval1";
        Password pass = new Password(passStr);
        String passKey = "pass1";
        props.put(passKey, pass);
        props.put("k2", "val2");

        CryptoService cryptoServiceMock = streamCryptoService();
        cs.setCryptoService(cryptoServiceMock);

        char[] decpass = "decpass".toCharArray();
        when(cryptoServiceMock.decryptAes(passStr.toCharArray())).thenReturn(decpass);

        assertEquals(2, props.size(), "config size");

        cs.decryptConfigurationProperties(config.getConfigurationProperties());

        verify(cryptoServiceMock, times(1)).decryptAes(passStr.toCharArray());

        Map<String, Object> result = config.getConfigurationProperties();
        assertNotNull(result, "properties not null");
        assertEquals(2, result.size(), "config properties size");
        assertTrue(result.containsKey(passKey), "contains password");
        assertArrayEquals(decpass, ((Password) result.get(passKey)).getPassword(), "decrypted pass OK");
        assertArrayEquals(decpass, ((Password) props.get(passKey)).getPassword(), "decrypted pass OK - reference");
    }

    @Test
    public void testDecryptPasswordsException() throws KuraException {
        // test error in password decryption
        ConfigurationServiceImpl cs = new TestConfigurationService();

        ComponentConfigurationImpl config = new ComponentConfigurationImpl();
        Map<String, Object> props = new HashMap<>();
        config.setProperties(props);
        Password pass = new Password("passval1");
        String passKey = "pass1";
        props.put(passKey, pass);

        CryptoService cryptoServiceMock = streamCryptoService();
        cs.setCryptoService(cryptoServiceMock);

        KuraException exc = new KuraException(KuraErrorCode.STORE_ERROR);
        when(cryptoServiceMock.decryptAes((char[]) ArgumentMatchers.any())).thenThrow(exc);

        assertEquals(1, props.size(), "config size before decryption");

        cs.decryptConfigurationProperties(config.getConfigurationProperties());

        verify(cryptoServiceMock, times(1)).decryptAes((char[]) ArgumentMatchers.any());

        assertEquals(1, props.size(), "config size after decryption");
    }

