    @Test
    public void testMergeWithDefaults() {
        // a few default values, a few overrides, one ovelap

        final Map<String, Object> props = new HashMap<>();
        String prop1Key = "prop1";
        String prop1DefValue = "prop1DefValue";
        props.put(prop1Key, prop1DefValue);
        props.put("defKey2", "defValue2");

        ConfigurationServiceImpl cs = new TestConfigurationService() {

            @Override
            Map<String, Object> getDefaultProperties(OCD ocd) {
                return props;
            }
        };

        Tocd ocd = new Tocd();
        Map<String, Object> properties = new HashMap<>();
        String prop1Value = "value1";
        properties.put(prop1Key, prop1Value);
        properties.put("key2", "value2");

        assertNotEquals(prop1Value, prop1DefValue);

        boolean merged = cs.mergeWithDefaults(ocd, properties);

        assertTrue(merged, "properties merged");
        assertEquals(3, properties.size(), "added a property");
        assertEquals(prop1Value, properties.get(prop1Key), "value override OK");
        assertTrue(properties.containsKey("key2"), "value override only");
        assertTrue(properties.containsKey("defKey2"), "default value only");
    }

